//! The one diagnostic assembly post-pass (P4-5a).
//!
//! Every checker surface decodes its backend's output into
//! [`FinishedDiagnostic`]s (generated byte ranges in the text the checker saw)
//! and calls [`assemble_diagnostics`] once per authored file. The pass owns
//! every decision about *which* diagnostics exist and *where* they land:
//! reportability, projection back to authored bytes, severity and code
//! rewrites, authored-message restoration, deduplication, authored
//! suppression comments and template diagnostic directives. Surfaces only
//! render the result (line/column encoding, private path spellings), so
//! `vize check` and the Maestro session cannot disagree about a diagnostic.

use core::cell::OnceCell;
use std::ops::Range;

use vize_carton::String;

use crate::batch::ImportSourceMap;
use crate::template_diagnostic_directives::{
    TemplateDiagnosticDirectives, UNUSED_EXPECT_ERROR_CODE, UNUSED_EXPECT_ERROR_MESSAGE,
};
use crate::virtual_ts::ProjectionMapping;

mod authored_rules;
mod dedup;
mod keyof;
mod rules;

pub use dedup::widen_leading_literal_type;
pub(crate) use rules::sfc_template_block_range;
pub use rules::{is_exhaustiveness_elaboration, is_reportable};

/// The authored file every projected document of one assembly maps into.
pub struct AuthoredSource<'a> {
    text: &'a str,
    is_vue: bool,
    template: OnceCell<Option<Range<usize>>>,
}

impl<'a> AuthoredSource<'a> {
    /// A Vue SFC; its template block range is computed on first use.
    pub fn vue(text: &'a str) -> Self {
        Self {
            text,
            is_vue: true,
            template: OnceCell::new(),
        }
    }

    /// A Vue SFC whose template block range the caller already knows.
    pub fn vue_with_template(text: &'a str, template: Option<Range<usize>>) -> Self {
        let source = Self::vue(text);
        let _ = source.template.set(template);
        source
    }

    /// A script file (no template, no template directives).
    pub fn script(text: &'a str) -> Self {
        let source = Self::vue_with_template(text, None);
        Self {
            is_vue: false,
            ..source
        }
    }

    /// The authored text.
    pub fn text(&self) -> &'a str {
        self.text
    }

    /// The SFC template block range (the same block `vize check` reports as
    /// `SfcBlockType::Template`).
    pub fn template(&self) -> Option<&Range<usize>> {
        self.template
            .get_or_init(|| rules::template_block_range(self.text))
            .as_ref()
    }
}

/// One generated document the checker saw, projecting the authored file.
pub struct ProjectedDocument<'a> {
    /// The generated text exactly as the checker saw it (import-rewritten).
    pub generated: &'a str,
    /// Import-rewrite offsets back to the pre-rewrite projection.
    pub import_map: &'a ImportSourceMap,
    /// Span links into the authored file; `None` projects byte for byte.
    pub mapping: Option<&'a ProjectionMapping>,
    /// Whether the generated text is TSX.
    pub tsx: bool,
}

/// A diagnostic the checker finished, in generated coordinates.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FinishedDiagnostic<P> {
    /// Index into the assembly's documents.
    pub document: usize,
    /// Generated byte range.
    pub start: usize,
    pub end: usize,
    pub code: Option<u32>,
    /// LSP severity (1 error … 4 hint); `None` when the checker sent none.
    pub severity: Option<u8>,
    pub message: String,
    /// Surface data carried through unchanged (e.g. the checker's own code
    /// spelling).
    pub payload: P,
}

/// Where an assembled diagnostic came from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AssembledOrigin<P> {
    /// A checker diagnostic projected onto authored bytes.
    Checker(P),
    /// A checker `TS2307` for a generated `.vue` import with no projected
    /// range, placed on the authored specifier.
    MissingVueImport(P),
    /// A template diagnostic directive nothing consumed.
    UnusedExpectation,
}

/// A diagnostic on authored bytes.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssembledDiagnostic<P> {
    /// Authored byte range.
    pub start: usize,
    pub end: usize,
    pub code: Option<u32>,
    pub severity: Option<u8>,
    pub message: String,
    pub origin: AssembledOrigin<P>,
}

/// The only surface-dependent input: whether unused-declaration diagnostics
/// (`TS6133`) are reportable. `vize check` reports them when the project's
/// tsconfig asks for them; an editor always shows what the checker sent
/// (usually as a faded hint).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AssemblyPolicy {
    pub report_unused: bool,
}

/// Assemble one authored file's finished diagnostics.
pub fn assemble_diagnostics<P>(
    authored: &AuthoredSource<'_>,
    documents: &[ProjectedDocument<'_>],
    finished: Vec<FinishedDiagnostic<P>>,
    policy: AssemblyPolicy,
) -> Vec<AssembledDiagnostic<P>> {
    let mut keyof_indexes: Vec<Option<keyof::AssignmentIndex>> =
        documents.iter().map(|_| None).collect();
    let mut assembled = Vec::with_capacity(finished.len());
    for diagnostic in finished {
        let Some(document) = documents.get(diagnostic.document) else {
            continue;
        };
        if !rules::is_reportable(
            diagnostic.code,
            diagnostic.severity,
            &diagnostic.message,
            policy,
        ) || rules::is_generated_vue_ts_import_extension(document.generated, &diagnostic)
        {
            continue;
        }
        if diagnostic.code == Some(2322)
            && keyof_indexes
                .get_mut(diagnostic.document)
                .is_some_and(|index| {
                    index
                        .get_or_insert_with(|| {
                            keyof::AssignmentIndex::new(document.generated, document.tsx)
                        })
                        .matches_at(diagnostic.start as u32)
                })
        {
            continue;
        }
        if let Some(diagnostic) = project(authored, document, diagnostic) {
            assembled.push(diagnostic);
        }
    }
    let mut assembled = dedup::dedup(assembled);
    authored_rules::filter(authored, &mut assembled);
    if authored.is_vue {
        apply_template_directives(authored, &mut assembled);
    }
    assembled
}

/// Place one reportable checker diagnostic on authored bytes and apply the
/// authored-position rules.
fn project<P>(
    authored: &AuthoredSource<'_>,
    document: &ProjectedDocument<'_>,
    diagnostic: FinishedDiagnostic<P>,
) -> Option<AssembledDiagnostic<P>> {
    let pre_start = document
        .import_map
        .get_original_offset(diagnostic.start as u32) as usize;
    let pre_end = document
        .import_map
        .get_original_offset(diagnostic.end as u32) as usize;
    let projected = match document.mapping {
        Some(mapping) => mapping.diagnostic_range_to_authored(pre_start, pre_end),
        None => Some((pre_start, pre_end.max(pre_start))),
    };
    let FinishedDiagnostic {
        start,
        code,
        severity,
        message,
        payload,
        ..
    } = diagnostic;
    let Some((authored_start, authored_end)) = projected else {
        return rules::missing_vue_import(authored.text, code, severity, message, payload);
    };
    if rules::is_authored_vue_import_extension(
        authored.text,
        code,
        &message,
        authored_start,
        authored_end,
    ) {
        return None;
    }
    let severity = if is_unreachable_warning(document.generated, start, code, &message) {
        Some(2)
    } else {
        severity
    };
    // Only a lexical lookup failure can become an instance diagnostic, so the
    // template range is computed for nothing else.
    let (code, message) = match code {
        Some(lookup)
            if crate::template_instance_names::is_lexical_lookup_failure(lookup)
                && authored
                    .template()
                    .is_some_and(|template| template.contains(&authored_start)) =>
        {
            match crate::template_instance_names::instance_diagnostic(lookup, &message) {
                Some((code, message)) => (Some(code), message),
                None => (code, message),
            }
        }
        _ => (code, message),
    };
    Some(AssembledDiagnostic {
        start: authored_start,
        end: authored_end,
        code,
        severity,
        message: crate::batch::restore_virtual_vue_specifiers(&message, authored.text),
        origin: AssembledOrigin::Checker(payload),
    })
}

/// A generated reachability assertion is a warning unless the checker
/// elaborated it with anything but exhaustiveness chains.
fn is_unreachable_warning(generated: &str, start: usize, code: Option<u32>, message: &str) -> bool {
    crate::virtual_ts::is_unreachable_pattern_diagnostic(generated, start, code)
        && message.lines().skip(1).all(is_exhaustiveness_elaboration)
}

/// Template diagnostic directives: suppress what they cover and report the
/// expectations nothing consumed.
fn apply_template_directives<P>(
    authored: &AuthoredSource<'_>,
    assembled: &mut Vec<AssembledDiagnostic<P>>,
) {
    let mut directives = TemplateDiagnosticDirectives::for_sfc(authored.text);
    if directives.directives().is_empty() {
        return;
    }
    assembled
        .retain(|diagnostic| diagnostic.code.is_none() || !directives.suppresses(diagnostic.start));
    for range in directives.unused_expectations() {
        assembled.push(AssembledDiagnostic {
            start: range.start,
            end: range.end,
            code: Some(UNUSED_EXPECT_ERROR_CODE),
            severity: Some(1),
            message: UNUSED_EXPECT_ERROR_MESSAGE.into(),
            origin: AssembledOrigin::UnusedExpectation,
        });
    }
}

